import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const ResetPassword = () => {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [tokenValid, setTokenValid] = useState(null);
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();

  const token = searchParams.get("token");

  useEffect(() => {
    // Verificar se o token está presente
    if (!token) {
      setMessage("Token inválido ou ausente");
      setTokenValid(false);
    } else {
      setTokenValid(true);
    }
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (newPassword !== confirmPassword) {
      setMessage("As senhas não coincidem");
      return;
    }

    setLoading(true);

    try {
      const response = await fetch(
        "http://localhost:5000/api/password-reset/reset-password",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ token, newPassword }),
        }
      );

      const data = await response.json();

      if (response.ok) {
        setMessage(data.message || "Senha redefinida com sucesso!");
        setTimeout(() => navigate("/login"), 2000);
      } else {
        setMessage(data.message || "Erro ao redefinir senha");
      }
    } catch (error) {
      console.error("Erro:", error);
      setMessage("Erro no servidor. Tente novamente mais tarde.");
    } finally {
      setLoading(false);
    }
  };

  if (tokenValid === false) {
    return (
      <div
        className="container-fluid d-flex justify-content-center align-items-center"
        style={{ minHeight: "100vh" }}
      >
        <div className="card p-4 shadow" style={{ width: "350px" }}>
          <h2 className="text-center text-danger">Erro</h2>
          <p className="text-center">{message}</p>
          <p className="text-center mt-3">
            <a href="/forgot-password">Solicitar novo link</a>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex justify-content-center align-items-center"
      style={{ minHeight: "100vh" }}
    >
      <div className="card p-4 shadow" style={{ width: "350px" }}>
        <h2 className="text-center">Redefinir Senha</h2>
        {message && (
          <div
            className={`alert ${
              message.includes("sucesso") ? "alert-success" : "alert-danger"
            }`}
          >
            {message}
          </div>
        )}
        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label">Nova Senha</label>
            <input
              type="password"
              className="form-control"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              placeholder="Digite sua nova senha"
              required
              minLength="6"
            />
          </div>
          <div className="mb-3">
            <label className="form-label">Confirmar Nova Senha</label>
            <input
              type="password"
              className="form-control"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Confirme sua nova senha"
              required
              minLength="6"
            />
          </div>
          <button
            type="submit"
            className="btn btn-primary w-100"
            disabled={loading || !tokenValid}
          >
            {loading ? (
              <>
                <span
                  className="spinner-border spinner-border-sm me-2"
                  role="status"
                  aria-hidden="true"
                ></span>
                Redefinindo...
              </>
            ) : (
              "Redefinir Senha"
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

export default ResetPassword;
